using System.Collections.Generic;
using GameJam.Gameplay;
using UnityEditor;
using UnityEngine;

namespace GameJam.Editor
{
    /// <summary>
    /// Puts the skinned porcupine player body (Art/Characters/PorcupineBody.fbx, generated by
    /// tools/blender/scripts/build_porcupine_body.py) on the player avatar and wires its <see cref="GorillaBodyRig"/>:
    /// bones by name, the project's URP materials (natural porcupine colours, the same for every player) by the FBX's
    /// material names, and generous skinned bounds so stretched arms never get culled. Returns null while the FBX is
    /// missing, so the avatar shows only its glove spheres.
    /// </summary>
    public static class GorillaBodyBuilder
    {
        public const string ModelPath = "Assets/GameJam/Art/Characters/PorcupineBody.fbx";

        /// <param name="parent">The avatar's body transform (follows the player's yaw).</param>
        /// <param name="headHeight">How far the head (the model's origin, the eyes) sits above <paramref name="parent"/>.</param>
        public static GorillaBodyRig Build(Transform parent, float headHeight)
        {
            ConfigureImport();
            var source = AssetDatabase.LoadAssetAtPath<GameObject>(ModelPath);
            if (source == null)
            {
                Debug.LogWarning($"[GorillaBodyBuilder] {ModelPath} not found: run build_porcupine_body.py.");
                return null;
            }

            var instance = (GameObject)Object.Instantiate(source, parent, false);
            instance.name = "PorcupineBody";
            instance.transform.localPosition = new Vector3(0f, headHeight, 0f);
            instance.transform.localRotation = Quaternion.identity;
            if (instance.TryGetComponent(out Animator animator))
            {
                Object.DestroyImmediate(animator);
            }

            // Natural North American porcupine: near-black brown fur, warmer belly, cream-tipped quills; tan paw mitts
            // are the gloves (the safe part), light enough to read against the dark fur.
            var materials = new Dictionary<string, Material>
            {
                { "Fur", PlaceholderAssets.Material("PorcupineFur", new Color(0.20f, 0.14f, 0.09f), 0.15f) },
                { "Belly", PlaceholderAssets.Material("PorcupineBelly", new Color(0.36f, 0.26f, 0.17f), 0.15f) },
                { "Face", PlaceholderAssets.Material("PorcupineFace", new Color(0.13f, 0.09f, 0.07f), 0.25f) },
                { "Eye", PlaceholderAssets.Material("PorcupineEye", new Color(0.02f, 0.02f, 0.02f), 0.85f) },
                { "QuillBase", PlaceholderAssets.Material("PorcupineQuill", new Color(0.10f, 0.07f, 0.05f), 0.35f) },
                { "QuillTip", PlaceholderAssets.Material("PorcupineQuillTip", new Color(0.93f, 0.89f, 0.80f), 0.35f) },
                { "Paw", PlaceholderAssets.Material("PorcupinePaw", new Color(0.80f, 0.70f, 0.56f), 0.2f) },
            };

            SkinnedMeshRenderer body = Renderer(instance.transform, "Body", materials);
            SkinnedMeshRenderer arms = Renderer(instance.transform, "Arms", materials);

            var rig = instance.AddComponent<GorillaBodyRig>();
            rig.Configure(Bone(instance.transform, "Head"), Arm(instance.transform, "L"), Arm(instance.transform, "R"), body, arms);
            return rig;
        }

        /// <summary>
        /// Generic rig (Rig "None" would import the meshes unskinned), no animation clips; the Animator it adds is removed
        /// from the instance because GorillaBodyRig poses the bones in code.
        /// </summary>
        private static void ConfigureImport()
        {
            if (AssetImporter.GetAtPath(ModelPath) is not ModelImporter importer)
            {
                return;
            }

            bool changed = false;
            if (importer.animationType != ModelImporterAnimationType.Generic)
            {
                importer.animationType = ModelImporterAnimationType.Generic;
                changed = true;
            }

            if (importer.importAnimation)
            {
                importer.importAnimation = false;
                changed = true;
            }

            if (importer.importBlendShapes)
            {
                importer.importBlendShapes = false;
                changed = true;
            }

            if (changed)
            {
                importer.SaveAndReimport();
            }
        }

        private static SkinnedMeshRenderer Renderer(Transform root, string name, Dictionary<string, Material> materials)
        {
            Transform child = root.Find(name);
            if (child == null || !child.TryGetComponent(out SkinnedMeshRenderer renderer))
            {
                Debug.LogWarning($"[GorillaBodyBuilder] No skinned mesh '{name}' in {ModelPath}.");
                return null;
            }

            Material[] slots = renderer.sharedMaterials;
            for (int i = 0; i < slots.Length; i++)
            {
                string key = slots[i] != null ? slots[i].name : string.Empty;
                if (materials.TryGetValue(key, out Material replacement))
                {
                    slots[i] = replacement;
                }
            }

            renderer.sharedMaterials = slots;
            // Arms reach ~1 m from the shoulders and stretch past that: bounds that always cover them (root bone = Body).
            renderer.localBounds = new Bounds(new Vector3(0f, 0.4f, 0f), new Vector3(2.6f, 2.4f, 2.6f));
            renderer.updateWhenOffscreen = false;
            renderer.skinnedMotionVectors = false;
            return renderer;
        }

        private static GorillaBodyRig.Arm Arm(Transform root, string side) => new GorillaBodyRig.Arm
        {
            UpperArm = Bone(root, $"UpperArm.{side}"),
            Forearm = Bone(root, $"Forearm.{side}"),
            Hand = Bone(root, $"Hand.{side}"),
            GloveCenter = Bone(root, $"GloveCenter.{side}"),
        };

        private static Transform Bone(Transform root, string name)
        {
            foreach (Transform child in root.GetComponentsInChildren<Transform>(true))
            {
                if (child.name == name)
                {
                    return child;
                }
            }

            Debug.LogWarning($"[GorillaBodyBuilder] Bone '{name}' missing in {ModelPath}.");
            return null;
        }
    }
}
